mapper.select:
SELECT o.id AS orderId, o.order_no AS orderNo, o.customer_name AS customerName, o.customer_phone AS customerPhone, o.user_id AS userId, u.name AS userName, u.phone AS userPhone FROM orders o INNER JOIN "user" u ON o.user_id = u.id
AND o.user_id = #{userId}
AND u.phone = #{phone}
LIMIT 50
